import {T} from './core.js?v=75';
import {ENTRY_REPAIR} from './entry-terrain.js?v=75';
import {BUILDINGS} from './village-layout.js?v=75';
import {surfacePerimeter,nearestEdge,edgeSurface} from './surface-seams.js?v=75';
const ease=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);};
export function closeEntryPavingSeam(scene,m){scene.updateMatrixWorld(true);const b=ENTRY_REPAIR,inside=p=>p.x>=b.minX&&p.x<=b.maxX&&p.z>=b.minZ&&p.z<=b.maxZ,ground=[],walk=[],oldEdges=[];scene.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;if(o.material===m.meadow)ground.push(o);if(o.userData.villageTrafficSurface==='walk')walk.push(o);if(o.userData.villagePavingEdge)oldEdges.push(o);});const edges=walk.flatMap(surfacePerimeter).filter(e=>inside(e.a)||inside(e.b));let graded=0;
 // Grade both upwards and downwards, preserving the two house foundations.
 for(const mesh of ground){const g=mesh.geometry,p=g.attributes.position,next=p.clone(),modified=new Set(),inverse=mesh.matrixWorld.clone().invert();for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld);if(!inside(v))continue;const n=nearestEdge(v.x,v.z,edges);if(!n||n.distance>1.6)continue;let weight=ease((1.6-n.distance)/1.54)*ease(Math.min(v.x-b.minX,b.maxX-v.x,v.z-b.minZ,b.maxZ-v.z)/2);for(const house of BUILDINGS.filter(h=>['haus-7','haus-8'].includes(h.id))){const c=Math.cos(house.rot),s=Math.sin(house.rot),dx=v.x-house.x,dz=v.z-house.z,d=Math.hypot(Math.max(0,Math.abs(c*dx-s*dz)-house.w/2),Math.max(0,Math.abs(s*dx+c*dz)-house.d/2));weight*=ease((d-.85)/.7);}if(!weight)continue;v.y+=(n.y-.025-v.y)*weight;v.applyMatrix4(inverse);if(Math.abs(v.y-p.getY(i))<1e-6)continue;next.setXYZ(i,v.x,v.y,v.z);modified.add(i);graded++;}
 if(!modified.size)continue;const result=g.clone(),oldNormals=g.attributes.normal;result.setAttribute('position',next);result.computeVertexNormals();const affected=new Set(modified),ix=g.index;for(let i=0;i<(ix?.count??p.count);i+=3){const ids=[0,1,2].map(j=>ix?ix.getX(i+j):i+j);if(ids.some(j=>modified.has(j)))ids.forEach(j=>affected.add(j));}if(oldNormals)for(let i=0;i<p.count;i++)if(!affected.has(i))result.attributes.normal.setXYZ(i,oldNormals.getX(i),oldNormals.getY(i),oldNormals.getZ(i));mesh.geometry=result;mesh.userData.entryTerrainRepair=true;}
 const ray=new T.Raycaster(),height=p=>{ray.set(new T.Vector3(p.x,20,p.z),new T.Vector3(0,-1,0));return ray.intersectObjects(ground,false)[0]?.point.y??p.y-.1;};
 // Remove only the old local side faces; top paving remains identical.
 for(const mesh of oldEdges){const g=mesh.geometry,p=g.attributes.position,ix=g.index,keep=[];for(let i=0;i<ix.count;i+=3){const ids=[ix.getX(i),ix.getX(i+1),ix.getX(i+2)],v=ids.reduce((a,j)=>a.add(new T.Vector3().fromBufferAttribute(p,j).applyMatrix4(mesh.matrixWorld)),new T.Vector3()).multiplyScalar(1/3);if(!inside(v))keep.push(...ids);}const copy=g.clone();copy.setIndex(keep);mesh.geometry=copy;}
 const stone=new T.MeshStandardMaterial({name:'Geschlossener Natursteinanschluss am korrigierten Dorfeingang',color:'#777a72',roughness:.88});const local=edgeSurface(scene,stone,'Vollständig geschlossener Gehwegrand bei den zwei Wohnhäusern',edges,p=>Math.min(p.y-.04,height(p)-.10),{entryPavingSeam:true,revision:58,actualTerrainContact:true,walkTopPreserved:true});
 // Close the exposed upper terrain cut as well, where grass stood above paving.
 const grassEdges=ground.flatMap(surfacePerimeter).filter(e=>inside(e.a)&&inside(e.b)&&[e.a,e.b].every(p=>{const n=nearestEdge(p.x,p.z,edges);return n&&n.distance<.12&&p.y>n.y-.025;}));const bank=edgeSurface(scene,m.meadow,'Nahtloser begrünter Geländeanschluss an der Dorfeinfahrt',grassEdges,p=>Math.min(p.y-.02,nearestEdge(p.x,p.z,edges).y-.03),{entryTerrainClosure:true,revision:58});
 const marker=new T.Object3D();marker.name='Technisch geschlossener Straßen-Wiesen-Anschluss an der Dorfeinfahrt';marker.userData={entrySeamRepair:true,revision:58,reconstructedLowerVertices:edges.length*2,closedEdgeTriangles:local?.geometry.index.count/3||0,closedGrassTriangles:bank?.geometry.index.count/3||0,gradedTerrainVertices:graded,terrainMaterialPreserved:true,walkTopPreserved:true};scene.add(marker);return marker;
}
